export function parseEndLiquidationInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedEndLiquidationInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 8) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 8,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === MARGINFI_PROGRAM_ADDRESS ? undefined : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      marginfiAccount: getNextAccount(),
      liquidationRecord: getNextAccount(),
      group: getNextAccount(),
      liquidationReceiver: getNextAccount(),
      feeState: getNextAccount(),
      globalFeeWallet: getNextAccount(),
      systemProgram: getNextAccount(),
      feePayer: getNextOptionalAccount(),
    },
    data: getEndLiquidationInstructionDataDecoder().decode(instruction.data),
  };
}
